31	export async function generate(input: {
32	  occasion: UiOccasion;
33	  formality: number | null;
34	  mustColors: string[];
35	  city?: { lat: number; lon: number; label: string; source: LocationSource };
36	}): Promise<GenerateResult> {
37	  try {
38	    const supabase = await createClient();
39	    const {
40	      data: { user },
41	    } = await supabase.auth.getUser();
42	    if (!user) return { status: "error", message: "Not signed in" };
43	
44	    const { data: profile } = await supabase
45	      .from("profiles")
46	      .select(
47	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source",
48	      )
49	      .eq("id", user.id)
50	      .single();
51	    const { data: itemsRaw } = await supabase
52	      .from("items")
53	      .select("*")
54	      .eq("user_id", user.id)
55	      .eq("archived", false);
56	    const items = itemsRaw ?? [];
57	    const byId = new Map(items.map((i) => [i.id, i]));
58	
59	    const loc = resolveLocation({ input: input.city, profile });
60	
61	    const now = new Date();
62	    const f = await fetchForecast(loc.lat, loc.lon);
63	    const advice = laterAdvice(f.hourly);
64	    const weather: WeatherPayload = {
65	      tempC: f.tempC,
66	      feelsLikeC: f.feelsLikeC,
67	      condition: f.condition,
68	      cityLabel: loc.label,
69	      timezone: f.timezone,
70	      locationOrigin: loc.origin,
71	      laterSentence: advice.sentence,
72	      adviceClause: advice.adviceClause,
73	      laterLabel: "Later",
74	      hourly: f.hourly,
75	    };
76	
77	    const candItems: CandidateItem[] = items.map((i) => ({
78	      id: i.id,
79	      category: i.category,
80	      colors: i.colors ?? [],
81	      formality: i.formality,
82	      seasons: i.seasons ?? [],
83	      material: i.material,
84	    }));
85	    // Occasion gives the context; the user's onboarding dress codes narrow it;
86	    // an explicit Refine formality overrides both.
87	    const band = applyFormalityOverride(
88	      personalBand(input.occasion, profile),
89	      input.formality,
90	    );
91	    const candidateArgs = {
92	      band,
93	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
94	      season: currentSeason(now),
95	      excludeItemIds: [],
96	      mustColors: input.mustColors,
97	      maxAccessories: 1,
98	    };
99	    const combos = buildCandidates(candItems, candidateArgs);
100	    if (combos.length === 0) {
101	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
102	    }
103	
104	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
105	    const top = rankTopN(combos, { aesthetic, band }, 20);
106	
107	    const { picks } = await rerank({
108	      combos: top.map((t) =>
109	        t.items.map((ci) => {
110	          const it = byId.get(ci.id)!;
111	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
112	        }),
113	      ),
114	      aesthetic,
115	      occasion: input.occasion,
116	      weatherLabel: f.condition,
117	      tempC: f.tempC,
118	    });
119	
120	    const paths = Array.from(
121	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
122	    );
123	    const signed = await signItemImages(paths);
124	
125	    const looks: Look[] = picks.map((p) => {
126	      const combo = top[p.combo_index]?.items ?? top[0].items;
127	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
128	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
129	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
130	        itemId: d.id,
131	        category: d.category,
132	        subcategory: d.subcategory ?? null,
133	        brand: d.brand ?? null,
134	        name: d.name ?? null,
135	        colors: d.colors ?? [],
136	        cutoutUrl: signed.get(displayPath(d)) ?? "",
137	        slot: slots[idx],
138	      }));
139	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
140	    });
141	
142	    return { status: "ok", weather, looks };
143	  } catch (e) {
144	    console.error("[generate] failed:", e);
145	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
146	  }
147	}
