1	import { weatherRules, type Weather } from "./rules";
2	
3	export type CandidateItem = {
4	  id: string;
5	  category: string; // DB TitleCase: Tops/Bottoms/Outerwear/Shoes/Accessories/Fragrance
6	  colors: string[];
7	  formality: number | null;
8	  seasons: string[];
9	  material: string | null;
10	};
11	
12	export type CandidateArgs = {
13	  band: [number, number];
14	  weather: Weather;
15	  season: string;
16	  excludeItemIds: string[];
17	  mustColors: string[];
18	  maxAccessories: number;
19	};
20	
21	const CAP = 200;
22	
23	/** The required slots — a combo cannot exist without one of each. */
24	export const REQUIRED_CATEGORIES = ["Tops", "Bottoms", "Shoes"] as const;
25	export type RequiredCategory = (typeof REQUIRED_CATEGORIES)[number];
26	
27	/**
28	 * How far BELOW a band's floor an item may still qualify.
29	 *
30	 * Footwear gets a wider stretch than everything else because formality is a
31	 * poor fit for shoes: a clean minimal leather sneaker is genuinely valid
32	 * smart-casual work wear, so an f=2 sneaker should reach Work [3, 4.5]. The
33	 * stretch is deliberately one step, not unlimited — it lets sneakers into Work
34	 * but NOT into Evening [3.5, 5], and never lets an f=1 shoe into Work.
35	 */
36	function floorTolerance(category: string): number {
37	  return category === "Shoes" ? 1 : 0.5;
38	}
39	
40	function isEligible(i: CandidateItem, a: CandidateArgs, excludeMaterials: string[]): boolean {
41	  const [lo, hi] = a.band;
42	  if (i.category === "Fragrance") return false; // D11: fragrances are never slotted
43	  if (a.excludeItemIds.includes(i.id)) return false;
44	  if (i.material && excludeMaterials.includes(i.material.toLowerCase())) return false;
45	  if (i.seasons.length && !i.seasons.includes(a.season)) return false;
46	  const f = i.formality ?? 3;
47	  return f >= lo - floorTolerance(i.category) && f <= hi + 0.5;
48	}
49	
50	/** Per-category counts of what survived filtering — lets an empty result explain itself. */
51	export function eligibility(items: CandidateItem[], a: CandidateArgs): Record<string, number> {
52	  const { excludeMaterials } = weatherRules(a.weather);
53	  const counts: Record<string, number> = {};
54	  for (const i of items) {
55	    if (!isEligible(i, a, excludeMaterials)) continue;
56	    counts[i.category] = (counts[i.category] ?? 0) + 1;
57	  }
58	  for (const c of REQUIRED_CATEGORIES) counts[c] ??= 0;
59	  counts.Outerwear ??= 0;
60	  return counts;
61	}
62	
63	/**
64	 * Which required slot came up empty, or null if the closet can dress this band.
65	 * The screen uses this to say WHICH gap blocked the outfit instead of a generic
66	 * "add more pieces". Outerwear is never a reason — it does not block (see below).
67	 */
68	export function missingCategory(items: CandidateItem[], a: CandidateArgs): RequiredCategory | null {
69	  const counts = eligibility(items, a);
70	  return REQUIRED_CATEGORIES.find((c) => counts[c] === 0) ?? null;
71	}
72	
73	export function buildCandidates(items: CandidateItem[], a: CandidateArgs): CandidateItem[][] {
74	  const { needsOuterwear, excludeMaterials } = weatherRules(a.weather);
75	
76	  const eligible = items.filter((i) => isEligible(i, a, excludeMaterials));
77	
78	  const byCat = (c: string) => eligible.filter((i) => i.category === c);
79	  const tops = byCat("Tops");
80	  const bottoms = byCat("Bottoms");
81	  const shoes = byCat("Shoes");
82	  const outer = byCat("Outerwear");
83	  const accessories = byCat("Accessories");
84	
85	  const combos: CandidateItem[][] = [];
86	  for (const t of tops)
87	    for (const b of bottoms)
88	      for (const s of shoes) {
89	        // Outerwear is a PREFERENCE, not a requirement: layer it in when the cold
90	        // calls for it and the closet has one, but never refuse to dress someone
91	        // who owns no coat — that silently killed every outfit below 15°.
92	        // The weather strip's "Later" advice is what tells them to take a layer.
93	        const base = needsOuterwear && outer.length ? [t, b, s, outer[0]] : [t, b, s];
94	        combos.push(base); // required base (± outerwear), no accessory
95	        if (a.maxAccessories > 0 && accessories.length) {
96	          combos.push([...base, accessories[0]]); // optional, capped accent
97	        }
98	      }
99	
100	  const filtered = a.mustColors.length
101	    ? combos.filter((c) => a.mustColors.every((mc) => c.some((i) => i.colors.includes(mc))))
102	    : combos;
103	
104	  return filtered.slice(0, CAP);
105	}
