1	const NEUTRALS = new Set([
2	  "navy", "grey", "gray", "beige", "white", "black", "brown", "cream", "tan", "stone",
3	  "charcoal", "khaki", "ecru",
4	]);
5	
6	export function isNeutral(color: string): boolean {
7	  return NEUTRALS.has(color.trim().toLowerCase());
8	}
9	
10	/** 1.0 = all neutral; each accent beyond the first costs 0.25. */
11	export function colorHarmonyScore(colors: string[]): number {
12	  const accents = colors.filter((c) => !isNeutral(c)).length;
13	  const penalty = Math.max(0, accents - 1) * 0.25;
14	  return Math.min(1, Math.max(0, 1 - penalty));
15	}
