3	export function rankTopN<T extends ScoreItem>(combos: T[][], ctx: Ctx, n = 20) {
4	  return combos
5	    .map((items) => ({ items, score: scoreCombo(items, ctx) }))
6	    .sort((a, b) => b.score - a.score)
7	    .slice(0, n);
8	}
