1	import { colorHarmonyScore } from "./color";
2	
3	export type ScoreItem = {
4	  category: string;
5	  colors: string[];
6	  formality: number | null;
7	  style_tags?: string[];
8	};
9	export type Ctx = { aesthetic: string[]; band: [number, number] };
10	
11	/** 1.0 = identical formality; falls off with spread. */
12	export function formalityCoherence(formalities: number[]): number {
13	  const f = formalities.filter((x) => typeof x === "number");
14	  if (f.length < 2) return 1;
15	  const spread = Math.max(...f) - Math.min(...f);
16	  return Math.max(0, 1 - spread / 4); // spread of 4 (1↔5) → 0
17	}
18	
19	export function scoreCombo(items: ScoreItem[], ctx: Ctx): number {
20	  const colors = items.flatMap((i) => i.colors);
21	  const harmony = colorHarmonyScore(colors);
22	  const coherence = formalityCoherence(items.map((i) => i.formality ?? 3));
23	  const dnaHits = items.filter((i) => i.style_tags?.some((t) => ctx.aesthetic.includes(t))).length;
24	  const dna = items.length ? dnaHits / items.length : 0;
25	  return Math.min(1, 0.45 * harmony + 0.35 * coherence + 0.2 * dna);
26	}
