- [ ] **Step 3: Write minimal implementation**

```ts
/**
 * Ask "what's today?" only on a genuinely blank day.
 *
 * The question is a one-tap intent, not a gate: the moment the user has looks,
 * they are never asked again that day. Derived from what is stored rather than
 * a separate "asked" flag, so there is no second source of truth to drift.
 */
export function shouldAskIntent(occasionsGeneratedToday: string[]): boolean {
  return occasionsGeneratedToday.length === 0;
}

/** Beyond this the morning's outfit may genuinely be the wrong call. */
const TEMP_SWING_C = 5;

function isWet(condition: string): boolean {
  return /rain|drizzle|shower|snow|sleet|thunder/i.test(condition);
}

/**
 * Has the day moved enough that today's looks deserve a second opinion?
 *
 * Used only to OFFER a regenerate. Never regenerate on drift automatically:
 * that would spend the user's quota and replace looks they may already have
 * dressed in.
 */
export function weatherDrifted(
  snapshot: { tempC: number; condition: string },
  current: { tempC: number; condition: string },
): boolean {
  if (!Number.isFinite(snapshot.tempC)) return false;
  if (Math.abs(current.tempC - snapshot.tempC) >= TEMP_SWING_C) return true;
  return isWet(snapshot.condition) !== isWet(current.condition);
}
```

