/** Which occasions already have a stored set for this local day. */
export async function occasionsGeneratedToday(
  userId: string,
  generatedOn: string,
): Promise<string[]> {
  const supabase = await createClient();
  const { data } = await supabase
    .from("outfits")
    .select("occasion")
    .eq("user_id", userId)
    .eq("generated_on", generatedOn);
  return Array.from(new Set((data ?? []).map((r) => r.occasion).filter(Boolean) as string[]));
}
```

