/**
 * What the client needs BEFORE deciding whether to ask "what's today?".
 *
 * Deliberately cheap: no candidate building, no AI. It exists so the first
 * paint can be the question rather than a spinner in front of a question.
 */
export async function todayStatus(city?: {
  lat: number;
  lon: number;
  label: string;
  source: LocationSource;
}): Promise<{ occasions: string[]; weather: WeatherPayload | null }> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return { occasions: [], weather: null };

  const { data: profile } = await supabase
    .from("profiles")
    .select("location_lat, location_lon, location_label, location_source")
    .eq("id", user.id)
    .single();

  const loc = resolveLocation({ input: city, profile });
  const f = await fetchForecast(loc.lat, loc.lon);
  const advice = laterAdvice(f.hourly);
  const weather: WeatherPayload = {
    tempC: f.tempC,
    feelsLikeC: f.feelsLikeC,
    condition: f.condition,
    cityLabel: loc.label,
    timezone: f.timezone,
    locationOrigin: loc.origin,
    laterSentence: advice.sentence,
    adviceClause: advice.adviceClause,
    laterLabel: "Later",
    hourly: f.hourly,
  };

  const occasions = await occasionsGeneratedToday(user.id, localDateFor(new Date(), f.timezone));
  return { occasions, weather };
}
```

