```ts
export type Plan = "free" | "plus";
export type Decision = { allowed: boolean; remaining: number; limit: number };

/**
 * Regenerations per local day, by plan.
 *
 * This bounds ONLY explicit restyling. The daily drop — the first generation of
 * each occasion each day — is free on every plan, because rationing the core
 * ritual would make the free tier feel broken rather than limited (Decision 4).
 */
const REGENERATE_LIMIT: Record<Plan, number> = {
  free: 3,
  plus: Infinity,
};

export function decideGeneration(
  plan: Plan,
  isRegenerate: boolean,
  regeneratesToday: number,
): Decision {
  // Unknown plans fall back to the free rules. Failing open would make a typo
  // in a plan name silently hand out unlimited generation.
  const limit = REGENERATE_LIMIT[plan] ?? REGENERATE_LIMIT.free;

  if (!isRegenerate) return { allowed: true, remaining: Math.max(0, limit - regeneratesToday), limit };

  return {
    allowed: regeneratesToday < limit,
    remaining: Math.max(0, limit - regeneratesToday),
    limit,
  };
}
```

