```ts
import { createClient } from "@/lib/supabase/server";
import { decideGeneration, type Decision, type Plan } from "./quota-policy";

/**
 * The single gate every real AI generation passes through.
 *
 * Reads the plan and today's ledger, then defers the actual rule to the pure
 * policy — so changing tiers means editing quota-policy.ts and nothing else.
 */
export async function checkGeneration(
  userId: string,
  generatedOn: string,
  isRegenerate: boolean,
): Promise<Decision> {
  const supabase = await createClient();

  const { data: profile } = await supabase
    .from("profiles")
    .select("plan")
    .eq("id", userId)
    .single();

  const { count } = await supabase
    .from("generation_events")
    .select("id", { count: "exact", head: true })
    .eq("user_id", userId)
    .eq("generated_on", generatedOn)
    .eq("is_regenerate", true);

  return decideGeneration((profile?.plan ?? "free") as Plan, isRegenerate, count ?? 0);
}

/** Append-only: a regenerate replaces its outfits rows, so this is the only record. */
export async function recordGeneration(
  userId: string,
  occasion: string,
  generatedOn: string,
  isRegenerate: boolean,
): Promise<void> {
  const supabase = await createClient();
  await supabase
    .from("generation_events")
    .insert({ user_id: userId, occasion, generated_on: generatedOn, is_regenerate: isRegenerate });
}
```

