```ts
/**
 * Only `cutout.png` is migrated. `original.jpg` is the photo shown on the item
 * detail screen and is already compressed — re-encoding it would be a
 * regression, not a saving.
 */
export function needsWebpBackfill(cutoutPath: string | null): boolean {
  return Boolean(cutoutPath) && cutoutPath!.endsWith("/cutout.png");
}

/** Same folder, same name, new extension — so nothing else has to be rewritten. */
export function webpPathFor(cutoutPath: string): string {
  return cutoutPath.replace(/\.png$/, ".webp");
}
```

