import type { UiOccasion } from "./types";

const VALID: UiOccasion[] = ["everyday", "work", "weekend", "evening"];

/**
 * Total parse of the `?occasion=` parameter.
 *
 * Occasion moved into the URL once each one became a persistent daily set:
