// the way a real @imgly cutout looks (garment opaque, background transparent).
const W = 400, H = 400;
const c = document.createElement('canvas');
c.width = W; c.height = H;
const ctx = c.getContext('2d');
// left half opaque red "garment", right half fully transparent "background"
const img = ctx.createImageData(W, H);
for (let i = 0; i < W*H; i++) {
  const x = i % W;
  const opaque = x < W/2;
  img.data[i*4] = 200; img.data[i*4+1] = 40; img.data[i*4+2] = 40;
  img.data[i*4+3] = opaque ? 255 : 0;
}
ctx.putImageData(img, 0, 0);

// source PNG blob (what @imgly returns)
const pngBlob = await new Promise(r => c.toBlob(r, 'image/png'));

// the WEBP_QUALITY=0.85 pass from encode.ts
