const oc = document.createElement('canvas');
oc.width = bitmap.width; oc.height = bitmap.height;
const octx = oc.getContext('2d');
octx.drawImage(bitmap, 0, 0);
const webpBlob = await new Promise(r => oc.toBlob(r, 'image/webp', 0.85));

